package views.helper

import play.twirl.api.Html

object Format {
  private val de = java.text.NumberFormat.getCurrencyInstance(java.util.Locale.GERMANY)
  def money(cents: Long): Html =
    Html(s"""<span class="money">${de.format(cents / 100.0)}</span>""")
}
